pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 minsum, uint256 amount, uint256 am) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.SetMinSum(minsum) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 bal;
        try c.balances(address(this)) returns (uint256 __r) { bal = __r; } catch { return; }
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        bool shouldSkip = (am > bal) || (bal < minsum);
        assertTrue(!shouldSkip || (!reverted && c.balances(address(this)) == bal));
    }

    function testFuzz_run(uint256 minsum, uint256 amount, uint256 am) public {
        _run(minsum, amount, am);
    }

    fallback() external payable {}

    receive() external payable {}
}
